import test from 'node:test';import assert from 'node:assert/strict';
import {create,move,preview,advance,policy,runPolicy} from './engine.js';
import {configureCapacity,setBudget} from './capacity.js';
import {validateRun,validateBundle,comparePolicy,portable,parse,markdown,editEffort} from './state.js';
const close=(a,b)=>assert.ok(Math.abs(a-b)<1e-8,`${a} != ${b}`);
test('value-only saved runs retain their accounting and do not acquire invented effort history',()=>{const legacy=runPolicy('tailor');assert.equal(legacy.capacity,undefined);assert.deepEqual(validateRun(legacy),legacy);const bundle=validateBundle({s:legacy,comparisons:[{id:'tailor',value:legacy.value}]});assert.equal(bundle.s.capacity,undefined);close(bundle.comparisons[0].value,legacy.value);assert.match(markdown(bundle),/Earlier value-only run/);});
test('effort estimates are independent of value points and displace named core work',()=>{let s=move(create({finite:true}),'export','tailored');let p=preview(s);close(p.capacity.required,3.25);close(p.capacity.coreDone,8.75);close(p.capacity.work[0].remainingAfter,1.25);close(p.capacity.maintenanceDisplaced,1.25);const oldNet=p.net;s=editEffort(s,'export','maintenance',3);p=preview(s);close(p.net,oldNet);close(p.capacity.coreDone,7);close(p.capacity.maintenanceDisplaced,3);assert.throws(()=>editEffort(s,'audit','setup',1),/first settlement/);});
test('capacity is conserved; partial core work carries into later quarters in arrival order',()=>{let s=create({finite:true});s=move(s,'export','tailored');for(let q=0;q<6;q++){const p=preview(s).capacity;assert.ok(p.feasible);close(p.required+p.coreDone+p.spare,p.budget);close(p.setup+p.maintenance+p.retirement,p.required);p.work.forEach(j=>close(j.remainingBefore,j.delivered+j.remainingAfter));s=advance(s);}const q2=s.history[1].capacity;close(q2.work.find(j=>j.id==='onboard').remainingBefore,1.25);close(q2.work.find(j=>j.id==='onboard').remainingAfter,0);assert.ok(q2.work.find(j=>j.id==='diagnose').delivered>0);close(s.history.reduce((n,h)=>n+h.capacity.coreDone,0)+s.history.at(-1).capacity.coreRemaining,s.capacity.jobs.reduce((n,j)=>n+j.effort,0));});
test('over-budget plans earn no settlement and leave the prior state unchanged',()=>{let s=move(create({finite:true}),'export','standard');s=move(s,'invoice','standard');const bytes=JSON.stringify(s),p=preview(s);assert.ok(!p.capacity.feasible);assert.equal(p.capacity.coreDone,0);assert.equal(p.capacity.maintenanceDisplaced,null);assert.throws(()=>advance(s),/before settling/);assert.equal(JSON.stringify(s),bytes);s=setBudget(s,0,p.capacity.required);const h=advance(s).history[0].capacity;close(h.required,h.budget);close(h.coreDone,0);});
test('expired benefit still requires upkeep; retirement consumes explicit effort and releases future capacity',()=>{let s=advance(move(create({finite:true}),'invoice','tailored'));s=advance(s);close(preview(s).revenue,0);assert.ok(preview(s).capacity.maintenance>0);s=move(s,'invoice','retired');let p=preview(s);close(p.capacity.maintenance,0);close(p.capacity.retirement,1);s=advance(s);close(preview(s).capacity.retirement,0);close(preview(s).capacity.maintenance,0);});
test('standardisation reduces effort for shared surfaces and new related setup',()=>{let s=advance(move(create({finite:true}),'export','standard'));s=move(s,'audit','tailored');const p=preview(s).capacity;close(p.setup,1.5);close(p.pairs[0].effort,.5/3);close(p.items.find(x=>x.id==='export').maintenance,.5);close(p.maintenance,p.items.reduce((n,x)=>n+x.maintenance,0)+p.pairs.reduce((n,x)=>n+x.effort,0));});
test('only future budgets and unsettled revealed estimates may change; replays use the same schedule',()=>{let s=advance(create({finite:true}));assert.throws(()=>setBudget(s,0,20));assert.throws(()=>configureCapacity(s,{aging:1}));assert.throws(()=>editEffort(s,'export','setup',1));s=editEffort(s,'audit','standard',6);s=setBudget(s,2,20);assert.deepEqual(validateRun(s),s);const high=create({finite:true});high.capacity.budgets.fill(40);for(const kind of ['tailor','reuse']){const r=comparePolicy(high,kind);assert.ok(r.complete);assert.deepEqual(r.history.map(h=>h.capacity.budget),high.capacity.budgets);close(r.coreDone,high.capacity.jobs.reduce((n,j)=>n+j.effort,0));}assert.equal(comparePolicy(create({finite:true}),'tailor').complete,false);});
test('portable runs preserve decisions, plans and effort; malformed histories reject before replacement',()=>{let s=advance(move(create({finite:true}),'export','tailored'));s=move(s,'audit','standard');const b={s,decision:'Protect release checks before accepting the bundle.',comparisons:[]},text=portable(b);assert.deepEqual(parse(text),b);assert.match(markdown(b),/Protect release checks/);for(const mutate of [b=>b.s.history[0].net+=1,b=>b.s.entries[0].status='standard',b=>b.s.capacity.budgets[0]=-1,b=>b.s.capacity.jobs[1].id=b.s.capacity.jobs[0].id]){const bad=structuredClone(b);mutate(bad);assert.throws(()=>validateBundle(bad));assert.equal(portable(b),text);}});
test('maintenance displaces no core work when spare capacity can already serve the whole queue',()=>{let s=move(create({finite:true}),'export','tailored');s=setBudget(s,0,40);const p=preview(s).capacity;assert.ok(p.maintenance>0);close(p.maintenanceDisplaced,0);close(p.allDisplaced,0);assert.ok(p.spare>0);});
